module.exports = {"style.css":"/* FanSided Recruit: one plain stylesheet. */\n:root {\n  --text: #1d1d1f;\n  --muted: #666;\n  --border: #d6d6d6;\n  --bg-soft: #f6f6f6;\n  --accent: #0b5cad;\n  --danger: #b3261e;\n  --ok-bg: #e7f4ea;\n  --err-bg: #fdecea;\n  --highlight: #fff3c4;\n}\n\n* { box-sizing: border-box; }\nbody {\n  margin: 0;\n  font: 15px/1.5 -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  color: var(--text);\n  background: #fff;\n}\nmain { max-width: 1100px; margin: 0 auto; padding: 1rem 1.25rem 3rem; }\nh1 { font-size: 1.6rem; margin: 0.5rem 0 0.75rem; }\nh2 { font-size: 1.2rem; margin: 1.25rem 0 0.5rem; }\nh3 { font-size: 1rem; margin: 1rem 0 0.4rem; }\na { color: var(--accent); }\ncode { background: var(--bg-soft); padding: 0 0.25em; border-radius: 3px; }\nhr { border: 0; border-top: 1px solid var(--border); margin: 1.5rem 0; }\n\n.topnav {\n  display: flex; flex-wrap: wrap; align-items: center; gap: 1rem;\n  padding: 0.6rem 1.25rem; border-bottom: 1px solid var(--border); background: var(--bg-soft);\n}\n.topnav a { text-decoration: none; }\n.topnav .brand { font-weight: 700; color: var(--text); }\n.spacer { flex: 1; }\n\n.muted { color: var(--muted); }\n.pre { white-space: pre-wrap; overflow-wrap: anywhere; }\n.narrow { max-width: 480px; }\n.req { color: var(--danger); }\n.error { color: var(--danger); font-size: 0.9em; display: block; margin: -0.4rem 0 0.6rem; }\ntd .error, summary .error, .note .error { display: inline; margin: 0; }\n.tag { background: var(--bg-soft); border: 1px solid var(--border); border-radius: 3px; padding: 0 0.35em; font-size: 0.85em; }\n\n.flash { padding: 0.6rem 0.8rem; border-radius: 4px; margin: 0.75rem 0; }\n.flash-ok { background: var(--ok-bg); }\n.flash-error { background: var(--err-bg); }\n\n/* Forms */\nform.stacked label { display: block; margin: 0 0 0.75rem; font-weight: 600; }\nform.stacked label .muted { font-weight: 400; }\nform.stacked input[type=text], form.stacked input[type=email], form.stacked input[type=url],\nform.stacked input[type=date], form.stacked textarea, form.stacked select {\n  display: block; width: 100%; margin-top: 0.25rem; font-weight: 400;\n}\ninput, textarea, select, button { font: inherit; }\ninput[type=text], input[type=email], input[type=url], input[type=date], textarea, select {\n  padding: 0.35rem 0.5rem; border: 1px solid var(--border); border-radius: 4px; background: #fff;\n}\nform.inline { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 0.4rem; margin: 0; }\nform.inline label { font-weight: 400; }\nbutton, .button {\n  display: inline-block; padding: 0.35rem 0.8rem; border: 1px solid var(--border); border-radius: 4px;\n  background: #fff; color: var(--text); cursor: pointer; text-decoration: none;\n}\nbutton:hover, .button:hover { background: var(--bg-soft); }\nbutton.primary { background: var(--accent); border-color: var(--accent); color: #fff; }\nbutton.primary:hover { filter: brightness(1.1); }\nbutton.danger, .button.danger { border-color: var(--danger); color: var(--danger); }\nbutton.link { border: 0; background: none; padding: 0; color: var(--accent); text-decoration: underline; }\nbutton.link.danger { color: var(--danger); }\nfieldset { border: 1px solid var(--border); border-radius: 4px; margin: 0 0 1rem; }\n.question-row { display: flex; gap: 1rem; align-items: flex-end; }\n.question-row label:first-child { flex: 1; }\n.question-row label.check { white-space: nowrap; }\n.hp { position: absolute; left: -10000px; width: 1px; height: 1px; overflow: hidden; }\n\n/* Tables */\ntable.data { width: 100%; border-collapse: collapse; margin: 0.5rem 0 1rem; }\ntable.data th, table.data td { text-align: left; padding: 0.4rem 0.5rem; border-bottom: 1px solid var(--border); vertical-align: middle; }\ntable.data th { background: var(--bg-soft); font-weight: 600; }\ntable.data .num { text-align: right; }\ntd.highlight { background: var(--highlight); font-weight: 700; }\ntr.clickable { cursor: pointer; }\ntr.clickable:hover { background: #fafafa; }\ntr.inactive td { color: var(--muted); }\n.status { font-size: 0.85em; padding: 0 0.4em; border-radius: 3px; border: 1px solid var(--border); }\n.status-open { background: var(--ok-bg); }\n.status-closed { background: var(--bg-soft); color: var(--muted); }\n.count { color: var(--muted); font-weight: 400; }\n\n/* Public */\nul.openings { list-style: none; padding: 0; }\nul.openings li { padding: 0.6rem 0; border-bottom: 1px solid var(--border); }\n.role-title { font-weight: 600; }\n.excerpt { color: var(--muted); }\n\n/* Candidate page */\n.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }\n@media (max-width: 800px) { .grid { grid-template-columns: 1fr; } }\n.card { border: 1px solid var(--border); border-radius: 6px; padding: 0.25rem 1rem 1rem; margin-bottom: 1rem; }\n.card.danger { border-color: var(--danger); }\n.details dt { font-weight: 600; margin-top: 0.6rem; }\n.details dd { margin: 0.15rem 0 0; }\nul.plain, ul.notes, ul.emails { list-style: none; padding: 0; margin: 0; }\n.note, ul.emails li { border-top: 1px solid var(--border); padding: 0.5rem 0; }\n.meta { color: var(--muted); font-size: 0.9em; }\nol.events { padding-left: 1.2rem; }\n.email-failed summary { color: var(--danger); }\n.role-header { background: var(--bg-soft); padding: 0.5rem 0.8rem; border-radius: 6px; }\n.toolbar { margin: 0 0 0.5rem; }\n\n/* Wide tables scroll sideways on small screens instead of overflowing the page. */\n.table-wrap { overflow-x: auto; -webkit-overflow-scrolling: touch; margin: 0.5rem 0 1rem; }\n.table-wrap table.data { margin: 0; }\ntable.data td { overflow-wrap: anywhere; }\ntable.data td.wrap { word-break: break-all; }\n.nowrap, form.inline.nowrap { flex-wrap: nowrap; white-space: nowrap; }\nform.inline.nowrap input[type=text] { min-width: 10rem; }\n#error-summary p { margin: 0.2rem 0; }\n#error-summary:focus { outline: 2px solid var(--danger); outline-offset: 2px; }\n\n/* Pipeline: every stage table uses the same column widths. */\ntable.pipeline { table-layout: fixed; min-width: 760px; }\ntable.pipeline col.c-name { width: 20%; }\ntable.pipeline col.c-email { width: 24%; }\ntable.pipeline col.c-date { width: 11%; }\ntable.pipeline col.c-source { width: 14%; }\ntable.pipeline col.c-days { width: 9%; }\ntable.pipeline col.c-move { width: 22%; }\ntable.pipeline form.inline { flex-wrap: nowrap; }\n.since { display: block; font-size: 0.75rem; font-weight: 600; color: #8a5a00; white-space: nowrap; }\ninput.wide { width: 100%; max-width: 48rem; font-family: monospace; }\n","app.js":"// Small progressive enhancements. Every page works without this file.\n(function () {\n  'use strict';\n\n  // Bring the apply form's error summary into view and focus.\n  var summary = document.getElementById('error-summary');\n  if (summary) summary.focus();\n\n  // Email hand-off page: follow the Gmail / mailto link on its own. Without JS the user clicks the link.\n  var handoff = document.querySelector('a[data-auto-open]');\n  if (handoff) {\n    var target = handoff.getAttribute('href') || '';\n    if (target.indexOf('https://mail.google.com/mail/?') === 0 || target.indexOf('mailto:') === 0) {\n      window.location.replace(target);\n    }\n  }\n\n  // Ask before destructive actions.\n  document.addEventListener('submit', function (e) {\n    var btn = e.submitter;\n    var msg = btn && btn.getAttribute('data-confirm');\n    if (msg && !window.confirm(msg)) e.preventDefault();\n  });\n\n  // Clicking a pipeline row opens the candidate (links and forms inside keep working).\n  document.addEventListener('click', function (e) {\n    var row = e.target.closest && e.target.closest('tr[data-href]');\n    if (!row) return;\n    if (e.target.closest('a, button, select, input, textarea, label, form')) return;\n    window.location.href = row.getAttribute('data-href');\n  });\n\n  // Show the Voltax fields only when \"Onboarded\" is picked.\n  document.querySelectorAll('.voltax-fields[data-show-for]').forEach(function (box) {\n    var form = box.closest('form');\n    var select = form && form.querySelector('select[name=\"stage\"]');\n    if (!select) return;\n    var update = function () {\n      var want = box.getAttribute('data-show-for');\n      box.hidden = select.value !== want || box.getAttribute('data-current') === want;\n    };\n    select.addEventListener('change', update);\n    update();\n  });\n})();\n"};
